  2561  static const xmlChar *
  2562  htmlParseHTMLName(htmlParserCtxtPtr ctxt) {
  2563      const xmlChar *ret;
  2564      int i = 0;
  2565      xmlChar loc[HTML_PARSER_BUFFER_SIZE];
  2566
  2567      if (!IS_ASCII_LETTER(CUR) && (CUR != '_') &&
  2568          (CUR != ':') && (CUR != '.')) return(NULL);
